const {chromium}=require('playwright');
const assert=require('node:assert/strict');
async function main(){
 const {createServer}=await import('vite');
 const server=await createServer({server:{host:'127.0.0.1',port:4222,strictPort:true}});await server.listen();
 const browser=await chromium.launch({executablePath:process.env.PLAYWRIGHT_EXECUTABLE_PATH||undefined,args:['--no-sandbox']});
 const page=await browser.newPage({viewport:{width:1280,height:850},reducedMotion:'reduce'});
 const errors=[];page.on('pageerror',e=>errors.push(e.message));
 try{
  await page.goto('http://127.0.0.1:4222/#/app/notifications');
  await page.getByRole('heading',{name:'ERP Notifications'}).waitFor();
  await page.getByLabel('Enable SMS service_ready').check();
  await page.getByLabel('SMS language').click();
  await page.getByRole('listbox',{name:'SMS language options'}).getByRole('option',{name:'Bangla'}).click();
  assert.match(await page.getByTestId('erp-sms-preview').innerText(),/পাঞ্জাবি/);
  await page.getByLabel('Notification trigger').click();
  await page.getByRole('listbox',{name:'Notification trigger options'}).getByRole('option',{name:'On event'}).click();
  await page.getByLabel('Filter notification group').click();
  await page.getByRole('listbox',{name:'Filter notification group options'}).getByRole('option',{name:'Loans & owner'}).click();
  await page.getByText('Borrower repayment reminder',{exact:true}).waitFor();
  await page.goto('http://127.0.0.1:4222/#/app/quotations');
  await page.getByRole('button',{name:'QT-000041',exact:true}).click();
  let quote=page.getByRole('dialog',{name:'Quotation QT-000041'});
  await quote.getByRole('button',{name:'Accepted'}).click();
  await quote.getByRole('button',{name:'Create online order'}).click();
  const editor=page.getByRole('dialog',{name:'New online order'});
  await editor.getByText('Linked accepted quotation',{exact:false}).waitFor();
  assert.equal(await editor.getByLabel('Order Quantity row 1', {exact:true}).isDisabled(),true);
  await editor.getByRole('button',{name:'Save order draft'}).click();
  await editor.waitFor({state:'hidden'});
  const order=page.locator('div.rounded-lg.border').filter({hasText:'Rahman Hardware'}).filter({hasText:'ON-000104'}).first();
  await order.getByRole('button',{name:'Open'}).click();
  let detail=page.getByRole('dialog',{name:'Online order ON-000104'});
  await detail.getByRole('button',{name:'Confirmed'}).click();
  await detail.getByRole('button',{name:'Packing list'}).click();
  let printable=page.getByRole('dialog',{name:'Print Packing list'});
  await printable.getByText('Packing checklist only',{exact:false}).waitFor();
  await printable.getByRole('button',{name:'Close',exact:true}).first().click();
  await detail.getByRole('button',{name:'Delivery challan'}).click();
  printable=page.getByRole('dialog',{name:'Print Delivery challan'});
  await printable.getByText('not a sales invoice',{exact:false}).waitFor();
  await printable.getByRole('button',{name:'Close',exact:true}).first().click();
  await detail.getByRole('button',{name:/Open in POS V2/}).click();
  await page.getByText('Prefilled from online order ON-000104',{exact:false}).waitFor();
  await page.getByText('NOT automatically added',{exact:false}).waitFor();
  await page.setViewportSize({width:375,height:812});
  await page.getByText('Prefilled from online order ON-000104',{exact:false}).waitFor();
  assert.deepEqual(errors,[]);
  console.log('ERP SMS and Quote→Order→Packing/Challan→POS desktop/mobile browser passed');
 }finally{await browser.close();await server.close();}
}
main().catch(e=>{console.error(e);process.exitCode=1;});
